/* Generated from spotify.astrale-theme.json. Consumer-owned after installation. */
:root,
[data-ui-preset='spotify'],
[data-ui-theme='spotify'] {
  color-scheme: light;
  --ui-background: oklch(0.99 0 0);
  --ui-foreground: oklch(0.35 0.02 165.48);
  --ui-card: oklch(1.00 0 0);
  --ui-card-foreground: oklch(0.35 0.02 165.48);
  --ui-popover: oklch(1.00 0 0);
  --ui-popover-foreground: oklch(0.35 0.02 165.48);
  --ui-primary: oklch(0.67 0.17 153.85);
  --ui-primary-foreground: oklch(0.99 0.02 169.99);
  --ui-secondary: oklch(0.90 0.02 238.66);
  --ui-secondary-foreground: oklch(0.20 0.02 266.02);
  --ui-muted: oklch(0.90 0.02 240.73);
  --ui-muted-foreground: oklch(0.50 0.03 268.53);
  --ui-accent: oklch(0.90 0.02 240.73);
  --ui-accent-foreground: oklch(0.35 0.02 165.48);
  --ui-destructive: oklch(0.61 0.24 20.96);
  --ui-destructive-foreground: oklch(0.99 0.02 169.99);
  --ui-border: oklch(0.94 0.01 238.46);
  --ui-input: oklch(0.85 0.02 240.75);
  --ui-ring: oklch(0.67 0.17 153.85);
  --ui-chart-1: oklch(0.67 0.17 153.85);
  --ui-chart-2: oklch(0.50 0.10 270.06);
  --ui-chart-3: oklch(0.72 0.12 201.79);
  --ui-chart-4: oklch(0.80 0.10 100.65);
  --ui-chart-5: oklch(0.60 0.15 300.14);
  --ui-sidebar: oklch(0.98 0.01 238.45);
  --ui-sidebar-foreground: oklch(0.35 0.02 165.48);
  --ui-sidebar-primary: oklch(0.67 0.17 153.85);
  --ui-sidebar-primary-foreground: oklch(0.98 0.01 238.45);
  --ui-sidebar-accent: oklch(0.90 0.02 240.73);
  --ui-sidebar-accent-foreground: oklch(0.35 0.02 165.48);
  --ui-sidebar-border: oklch(0.85 0.02 240.75);
  --ui-sidebar-ring: oklch(0.67 0.17 153.85);
  --ui-radius: 0.625rem;
  --ui-radius-panel: 0.625rem;
  --ui-control-height: 2.25rem;
  --ui-control-height-sm: 2rem;
  --ui-control-height-lg: 2.5rem;
  --ui-font-body: 'Merriweather', ui-serif, serif;
  --ui-font-heading: 'Lato', ui-sans-serif, sans-serif;
  --ui-font-mono: 'Roboto Mono', ui-monospace, monospace;
  --ui-shadow-control: 0px 1px 3px 0px oklch(0.35 0.05 163.50 / 0.02);
  --ui-shadow-panel:
    0px 1px 3px 0px oklch(0.35 0.05 163.50 / 0.04), 0px 4px 6px -1px oklch(0.35 0.05 163.50 / 0.04);
  --ui-motion-fast: 120ms;
  --ui-motion-standard: 180ms;
}

:root.dark,
[data-ui-preset='spotify'].dark,
[data-ui-theme='spotify'].dark {
  color-scheme: dark;
  --ui-background: oklch(0.15 0.02 269.18);
  --ui-foreground: oklch(0.95 0.01 238.46);
  --ui-card: oklch(0.20 0.02 266.02);
  --ui-card-foreground: oklch(0.95 0.01 238.46);
  --ui-popover: oklch(0.20 0.02 266.02);
  --ui-popover-foreground: oklch(0.95 0.01 238.46);
  --ui-primary: oklch(0.67 0.17 153.85);
  --ui-primary-foreground: oklch(0.15 0.02 269.18);
  --ui-secondary: oklch(0.30 0.03 271.05);
  --ui-secondary-foreground: oklch(0.95 0.01 238.46);
  --ui-muted: oklch(0.30 0.03 271.05);
  --ui-muted-foreground: oklch(0.60 0.03 269.46);
  --ui-accent: oklch(0.30 0.03 271.05);
  --ui-accent-foreground: oklch(0.95 0.01 238.46);
  --ui-destructive: oklch(0.64 0.25 19.69);
  --ui-destructive-foreground: oklch(0.15 0.02 269.18);
  --ui-border: oklch(0.95 0.01 238.46 / 15%);
  --ui-input: oklch(0.95 0.01 238.46 / 20%);
  --ui-ring: oklch(0.67 0.17 153.85);
  --ui-chart-1: oklch(0.67 0.17 153.85);
  --ui-chart-2: oklch(0.60 0.10 269.83);
  --ui-chart-3: oklch(0.72 0.12 201.79);
  --ui-chart-4: oklch(0.80 0.10 100.65);
  --ui-chart-5: oklch(0.60 0.15 300.14);
  --ui-sidebar: oklch(0.20 0.02 266.02);
  --ui-sidebar-foreground: oklch(0.95 0.01 238.46);
  --ui-sidebar-primary: oklch(0.67 0.17 153.85);
  --ui-sidebar-primary-foreground: oklch(0.15 0.02 269.18);
  --ui-sidebar-accent: oklch(0.30 0.03 271.05);
  --ui-sidebar-accent-foreground: oklch(0.95 0.01 238.46);
  --ui-sidebar-border: oklch(0.95 0.01 238.46 / 15%);
  --ui-sidebar-ring: oklch(0.67 0.17 153.85);
  --ui-radius: 0.625rem;
  --ui-radius-panel: 0.625rem;
  --ui-control-height: 2.25rem;
  --ui-control-height-sm: 2rem;
  --ui-control-height-lg: 2.5rem;
  --ui-font-body: 'Merriweather', ui-serif, serif;
  --ui-font-heading: 'Lato', ui-sans-serif, sans-serif;
  --ui-font-mono: 'Roboto Mono', ui-monospace, monospace;
  --ui-shadow-control: 0px 1px 3px 0px oklch(0.35 0.05 163.50 / 0.02);
  --ui-shadow-panel:
    0px 1px 3px 0px oklch(0.35 0.05 163.50 / 0.04), 0px 4px 6px -1px oklch(0.35 0.05 163.50 / 0.04);
  --ui-motion-fast: 120ms;
  --ui-motion-standard: 180ms;
}
